package com.dramenstaffalert;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("dramenStaffAlert")
public interface DramenStaffAlertConfig extends Config
{
	@ConfigItem(
		keyName = "highlightEquipped",
		position = 0,
		name = "Highlight when equipped",
		description = "Highlight fairy ring tiles when a Dramen/Lunar Staff is equipped or the Lumbridge & Draynor Elite Diary is complete"
	)
	default boolean highlightEquipped()
	{
		return true;
	}

	@ConfigItem(
		keyName = "equippedColor",
		position = 1,
		name = "Equipped highlight color",
		description = "Tile color when a staff is equipped or the elite diary is complete"
	)
	default Color equippedColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "highlightInventory",
		position = 2,
		name = "Highlight when in inventory",
		description = "Highlight fairy ring tiles when a Dramen/Lunar Staff is in inventory and still needs to be equipped"
	)
	default boolean highlightInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "inventoryColor",
		position = 3,
		name = "Inventory highlight color",
		description = "Tile color when a staff is in inventory and still needs to be equipped"
	)
	default Color inventoryColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "highlightMissing",
		position = 4,
		name = "Highlight when missing",
		description = "Highlight fairy ring tiles when a Dramen/Lunar Staff is required but neither equipped nor in inventory"
	)
	default boolean highlightMissing()
	{
		return true;
	}

	@ConfigItem(
		keyName = "missingColor",
		position = 5,
		name = "Missing highlight color",
		description = "Tile color when a staff is required but neither equipped nor in inventory"
	)
	default Color missingColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "showOverheadWarning",
		position = 6,
		name = "Show equip staff warning",
		description = "Show a local overhead reminder when clicking a fairy ring with a required staff in inventory but not equipped"
	)
	default boolean showOverheadWarning()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadWarningMessage",
		position = 7,
		name = "Equip staff warning message",
		description = "Local unequipped staff text. Supports chat effects"
	)
	default String overheadWarningMessage()
	{
		return "Equip your Dramen on Lunar staff";
	}

	@ConfigItem(
		keyName = "showMissingStaffWarning",
		position = 8,
		name = "Show missing staff warning",
		description = "Show a local overhead warning when clicking a fairy ring without a required staff equipped or in inventory"
	)
	default boolean showMissingStaffWarning()
	{
		return true;
	}

	@ConfigItem(
		keyName = "missingStaffWarningMessage",
		position = 9,
		name = "Missing staff warning message",
		description = "Local missing staff text. Supports chat effects"
	)
	default String missingStaffWarningMessage()
	{
		return "You don't have a Dramen or Lunar staff";
	}
}

package com.dramenstaffalert;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Dramen Staff Alert",
	description = "Alerts you when you need your Dramen/Lunar Staff equipped",
	tags = {"fairy", "ring", "dramen", "lunar", "staff", "alert", "tile"}
)
public class DramenStaffAlertPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FairyRingOverlay overlay;

	@Inject
	private StaffWarningOverlay staffWarningOverlay;

	private final Set<GameObject> fairyRings = new HashSet<>();
	private boolean active;

	@Provides
	@SuppressWarnings("unused") // Called by Guice to provide the plugin configuration.
	DramenStaffAlertConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DramenStaffAlertConfig.class);
	}

	@Override
	protected void startUp()
	{
		active = true;
		staffWarningOverlay.resetWarning();
		overlayManager.add(overlay);
		overlayManager.add(staffWarningOverlay);
		clientThread.invoke(() ->
		{
			if (active && client.getGameState() == GameState.LOGGED_IN)
			{
				// Scan once when enabling the plugin; subsequent updates use object events.
				for (Tile[][] plane : client.getTopLevelWorldView().getScene().getTiles())
				{
					for (Tile[] column : plane)
					{
						for (Tile tile : column)
						{
							if (tile != null)
							{
								for (GameObject object : tile.getGameObjects())
								{
									trackFairyRing(object);
								}
							}
						}
					}
				}
			}
		});
	}

	@Override
	protected void shutDown()
	{
		active = false;
		overlayManager.remove(overlay);
		overlayManager.remove(staffWarningOverlay);
		staffWarningOverlay.resetWarning();
		fairyRings.clear();
	}

	@Subscribe
	@SuppressWarnings("unused") // Called by RuneLite's event bus.
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		trackFairyRing(event.getGameObject());
	}

	@Subscribe
	@SuppressWarnings("unused") // Called by RuneLite's event bus.
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		fairyRings.remove(event.getGameObject());
	}

	@Subscribe
	@SuppressWarnings("unused") // Called by RuneLite's event bus.
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		if (action != MenuAction.GAME_OBJECT_FIRST_OPTION
			&& action != MenuAction.GAME_OBJECT_SECOND_OPTION
			&& action != MenuAction.GAME_OBJECT_THIRD_OPTION
			&& action != MenuAction.GAME_OBJECT_FOURTH_OPTION
			&& action != MenuAction.GAME_OBJECT_FIFTH_OPTION)
		{
			return;
		}

		if (isFairyRing(event.getId()))
		{
			staffWarningOverlay.triggerWarning();
		}
	}

	@Subscribe
	@SuppressWarnings("unused") // Called by RuneLite's event bus.
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING
			|| event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			fairyRings.clear();
		}
	}

	private void trackFairyRing(GameObject object)
	{
		if (object == null)
		{
			return;
		}

		if (isFairyRing(object.getId()))
		{
			fairyRings.add(object);
		}
	}

	private boolean isFairyRing(int objectId)
	{
		ObjectComposition definition = client.getObjectDefinition(objectId);
		if (definition.getImpostorIds() != null)
		{
			definition = definition.getImpostor();
		}
		// Match the named center object, excluding decorative ring edges and corners.
		return definition != null && ("Fairy ring".equalsIgnoreCase(definition.getName())
			|| definition.getId() == ObjectID.POH_FAIRY_RING
			|| definition.getId() == ObjectID.POH_SPIRIT_RING);
	}

	Set<GameObject> getFairyRings()
	{
		return fairyRings;
	}

	boolean meetsFairyRingStaffRequirement()
	{
		return client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1
			|| hasStaffEquipped();
	}

	private boolean hasStaffEquipped()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}

		Item weapon = equipment.getItem(KitType.WEAPON.getIndex());
		return weapon != null && (weapon.getId() == ItemID.DRAMEN_STAFF
			|| weapon.getId() == ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF);
	}

	boolean hasStaffInInventory()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && (inventory.contains(ItemID.DRAMEN_STAFF)
			|| inventory.contains(ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF));
	}
}

package com.dramenstaffalert;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class FairyRingOverlay extends Overlay
{
	private final Client client;
	private final DramenStaffAlertPlugin plugin;
	private final DramenStaffAlertConfig config;

	@Inject
	FairyRingOverlay(Client client, DramenStaffAlertPlugin plugin, DramenStaffAlertConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Color outline;
		if (plugin.meetsFairyRingStaffRequirement())
		{
			if (!config.highlightEquipped())
			{
				return null;
			}
			outline = config.equippedColor();
		}
		else if (plugin.hasStaffInInventory())
		{
			if (!config.highlightInventory())
			{
				return null;
			}
			outline = config.inventoryColor();
		}
		else
		{
			if (!config.highlightMissing())
			{
				return null;
			}
			outline = config.missingColor();
		}
		Color fill = new Color(outline.getRed(), outline.getGreen(), outline.getBlue(), 50);

		for (GameObject ring : plugin.getFairyRings())
		{
			if (ring.getWorldView() != client.getTopLevelWorldView()
				|| ring.getPlane() != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			Polygon tile = Perspective.getCanvasTilePoly(client, ring.getLocalLocation());
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, outline);
				graphics.setColor(fill);
				graphics.fillPolygon(tile);
			}
		}
		return null;
	}
}

package com.dramenstaffalert;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Parses public-chat style prefixes and draws their effects without sending chat. */
final class OverheadMessage
{
	private static final String[] COLORS = {
		"yellow", "red", "green", "cyan", "purple", "white",
		"flash1", "flash2", "flash3", "glow1", "glow2", "glow3", "rainbow"
	};
	private static final String[] MOTIONS = {"wave", "wave2", "shake", "scroll", "slide"};
	private static final int[] SOLID_COLORS = {0xffff00, 0xff0000, 0x00ff00, 0x00ffff, 0xff00ff, 0xffffff};
	private static final Pattern PATTERN_PREFIX = Pattern.compile("^pattern([0-9a-z]{1,8}):", Pattern.CASE_INSENSITIVE);
	// Public-chat pattern palette, indexed by keys 0-9 followed by a-z.
	private static final int[] PATTERN_COLORS = {
		0xffffff, 0xe40303, 0xff8c00, 0xffed00, 0x008026, 0x24408e,
		0x732982, 0xff218c, 0xb55690, 0x5049cc, 0xa3a3a3, 0xd52d00,
		0xef7627, 0xfcf434, 0x078d70, 0x21b1ff, 0x9b4f96, 0xffafc7,
		0xd162a4, 0x7bade3, 0xff9a56, 0x26ceaa, 0x73d7ee, 0x9c59d1,
		0x98e8c1, 0xb57edc, 0x2c2c2c, 0x940202, 0x613915, 0xd0c100,
		0x4a8123, 0x0038a8, 0x800080, 0xd60270, 0xa30262, 0x3d1a78
	};

	final String text;
	final int color;
	final String motion;
	private final int[] patternColors;

	private OverheadMessage(String text, int color, String motion, int[] patternColors)
	{
		this.text = text;
		this.color = color;
		this.motion = motion;
		this.patternColors = patternColors;
	}

	static OverheadMessage parse(String input)
	{
		String text = input;
		int color = 0;
		String motion = "";
		int[] patternColors = null;
		Matcher pattern = PATTERN_PREFIX.matcher(text);
		if (pattern.find())
		{
			String keys = pattern.group(1).toLowerCase(Locale.ROOT);
			patternColors = new int[keys.length()];
			for (int i = 0; i < keys.length(); i++)
			{
				patternColors[i] = PATTERN_COLORS[Character.digit(keys.charAt(i), 36)];
			}
			text = text.substring(pattern.end());
		}
		for (int i = 0; patternColors == null && i < COLORS.length; i++)
		{
			String prefix = COLORS[i] + ":";
			if (text.toLowerCase(Locale.ROOT).startsWith(prefix))
			{
				color = i;
				text = text.substring(prefix.length());
				break;
			}
		}
		for (String effect : MOTIONS)
		{
			String prefix = effect + ":";
			if (text.toLowerCase(Locale.ROOT).startsWith(prefix))
			{
				motion = effect;
				text = text.substring(prefix.length());
				break;
			}
		}
		return new OverheadMessage(text, color, motion, patternColors);
	}

	Color colorAt(int elapsed, int cycle, int character)
	{
		if (patternColors != null)
		{
			// Stretch the pattern into color bands across the entire text, rather than repeating per letter.
			int index = character * patternColors.length / Math.max(1, text.length());
			return new Color(patternColors[Math.min(index, patternColors.length - 1)]);
		}
		int rgb;
		if (color < SOLID_COLORS.length)
		{
			rgb = SOLID_COLORS[color];
		}
		else
		{
			boolean flash = cycle % 20 < 10;
			switch (color)
			{
				case 6: rgb = flash ? 0xff0000 : 0xffff00; break;
				case 7: rgb = flash ? 0x0000ff : 0x00ffff; break;
				case 8: rgb = flash ? 0x00b000 : 0x80ff80; break;
				case 9:
					rgb = elapsed < 50 ? 0xff0000 + elapsed * 1280
						: elapsed < 100 ? 0xffff00 - (elapsed - 50) * 327680
						: 0x00ff00 + (elapsed - 100) * 5;
					break;
				case 10:
					rgb = elapsed < 50 ? 0xff0000 + elapsed * 5
						: elapsed < 100 ? 0xff00ff - (elapsed - 50) * 327680
						: 0x0000ff + (elapsed - 100) * 327680 - (elapsed - 100) * 5;
					break;
				case 11:
					rgb = elapsed < 50 ? 0xffffff - elapsed * 327685
						: elapsed < 100 ? 0x00ff00 + (elapsed - 50) * 327685
						: 0xffffff - (elapsed - 100) * 327680;
					break;
				default:
					return Color.getHSBColor((float) character / Math.max(1, text.length()), 1, 1);
			}
		}
		return new Color(rgb);
	}

	void render(Graphics2D graphics, int centerX, int baseline, int elapsed, int cycle)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			FontMetrics metrics = g.getFontMetrics();
			int width = metrics.stringWidth(text);
			int x = centerX - width / 2;
			if (motion.equals("scroll"))
			{
				g.clipRect(centerX - 50, baseline - metrics.getHeight(), 100, metrics.getHeight() + 5);
				x = centerX + 50 - elapsed * (width + 100) / 150;
			}
			else if (motion.equals("slide"))
			{
				g.clipRect(centerX - width / 2 - 1, baseline - metrics.getHeight() - 1, width + 3, metrics.getHeight() + 6);
				baseline += elapsed < 25 ? elapsed - 25 : elapsed > 125 ? elapsed - 125 : 0;
			}

			for (int i = 0; i < text.length(); i++)
			{
				String glyph = text.substring(i, i + 1);
				int dx = 0;
				int dy = 0;
				switch (motion)
				{
					case "wave":
						dy = (int) (Math.sin(i / 2.0 + cycle / 5.0) * 5);
						break;
					case "wave2":
						dx = (int) (Math.sin(i / 5.0 + cycle / 5.0) * 5);
						dy = (int) (Math.sin(i / 3.0 + cycle / 5.0) * 5);
						break;
					case "shake":
						dy = (int) (Math.sin(i / 1.5 + cycle) * Math.max(0, 7 - elapsed / 8.0));
						break;
					default:
						break;
				}
				g.setColor(Color.BLACK);
				g.drawString(glyph, x + dx + 1, baseline + dy + 1);
				g.setColor(colorAt(elapsed, cycle, i));
				g.drawString(glyph, x + dx, baseline + dy);
				x += metrics.stringWidth(glyph);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.dramenstaffalert;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class StaffWarningOverlay extends Overlay
{
	// Normal player overhead chat lasts 150 client ticks (about three seconds).
	private static final int WARNING_DURATION_CYCLES = 150;

	private final Client client;
	private final DramenStaffAlertPlugin plugin;
	private final DramenStaffAlertConfig config;
	private boolean warningTriggered;
	private boolean missingStaffWarning;
	private int warningStartCycle;
	private String cachedMessage;
	private OverheadMessage styledMessage;

	@Inject
	StaffWarningOverlay(Client client, DramenStaffAlertPlugin plugin, DramenStaffAlertConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GameState gameState = client.getGameState();
		if (gameState != GameState.LOGGED_IN)
		{
			if (gameState == GameState.LOGIN_SCREEN || gameState == GameState.HOPPING)
			{
				resetWarning();
			}
			return null;
		}
		if (!warningTriggered)
		{
			return null;
		}
		boolean warningEnabled = missingStaffWarning ? config.showMissingStaffWarning() : config.showOverheadWarning();
		if (!warningEnabled || plugin.meetsFairyRingStaffRequirement()
			|| missingStaffWarning == plugin.hasStaffInInventory())
		{
			resetWarning();
			return null;
		}

		Player player = client.getLocalPlayer();
		String message = missingStaffWarning ? config.missingStaffWarningMessage() : config.overheadWarningMessage();
		if (player == null || message == null || message.trim().isEmpty())
		{
			resetWarning();
			return null;
		}

		int elapsed = client.getGameCycle() - warningStartCycle;
		if (elapsed >= WARNING_DURATION_CYCLES)
		{
			return null;
		}

		// Draw locally without replacing the player's real overhead chat or sending chat.
		if (!message.equals(cachedMessage))
		{
			cachedMessage = message;
			styledMessage = OverheadMessage.parse(message);
		}
		graphics.setFont(FontManager.getRunescapeBoldFont());
		Point location = player.getCanvasTextLocation(graphics, styledMessage.text, player.getLogicalHeight() + 40);
		if (location != null)
		{
			int centerX = location.getX() + graphics.getFontMetrics().stringWidth(styledMessage.text) / 2;
			styledMessage.render(graphics, centerX, location.getY(), elapsed, client.getGameCycle());
		}
		return null;
	}

	void triggerWarning()
	{
		resetWarning();
		if (client.getGameState() != GameState.LOGGED_IN || plugin.meetsFairyRingStaffRequirement())
		{
			return;
		}

		missingStaffWarning = !plugin.hasStaffInInventory();
		boolean warningEnabled = missingStaffWarning ? config.showMissingStaffWarning() : config.showOverheadWarning();
		if (warningEnabled)
		{
			warningTriggered = true;
			warningStartCycle = client.getGameCycle();
		}
	}

	void resetWarning()
	{
		warningTriggered = false;
		missingStaffWarning = false;
		warningStartCycle = 0;
		cachedMessage = null;
		styledMessage = null;
	}
}

