	public void onlyConsumesOneColorPrefix()
	{
		assertEquals("cyan:Hello", OverheadMessage.parse("patternq3:cyan:Hello").text);
		assertEquals("patternq3:Hello", OverheadMessage.parse("cyan:patternq3:Hello").text);
	}

